function matrix(p,n,m=n){return record(p)&&Array.isArray(p.shape)&&p.shape[0]===n&&p.shape[1]===m&&text(p.latex)&&Array.isArray(p.exact)&&p.exact.length===n&&p.exact.every(r=>Array.isArray(r)&&r.length===m&&r.every(text))&&['re','im'].every(k=>Array.isArray(p.numeric?.[k])&&p.numeric[k].length===n&&p.numeric[k].every(r=>Array.isArray(r)&&r.length===m&&r.every(num)));}
