function pattern(p,spinful){const site=s=>record(s)&&text(s.id)&&numericVector(s.position)&&numericVector(s.spin);return record(p)&&p.lab==='spin_group'&&p.dimension==='space'&&text(p.title)&&text(p.scope)&&Array.isArray(p.referenceSites)&&p.referenceSites.length===2&&p.referenceSites.every(site)&&Array.isArray(p.frames)&&p.frames.length===(spinful?5:4)&&p.frames.every(f=>record(f)&&Number.isInteger(f.step)&&text(f.label)&&bool(f.preservesPattern)&&Array.isArray(f.sites)&&f.sites.length===2&&f.sites.every(site))&&Array.isArray(p.cellVertices)&&p.cellVertices.length===8&&p.cellVertices.every(numericVector)&&Array.isArray(p.latticeAxes)&&p.latticeAxes.length===3&&p.latticeAxes.every(a=>record(a)&&text(a.label)&&numericVector(a.start)&&numericVector(a.end));}
function example(e,i){const s=e?.spectrum;return record(e)&&e.id===['unitary-gamma','antiunitary-z-plus'][i]&&e.spinful===true&&e.antiunitary===(i===1)&&Array.isArray(e.k)&&e.k.length===3&&e.k.every(x=>num(x)||text(x))&&e.energyUnits==='dimensionless model units'&&['title','description','scope','formula'].every(k=>text(e[k]))&&['symmetryMatrix','operatorSquare','hamiltonian','symmetryResidual'].every(k=>matrix(e[k],4))&&bool(e.preservesHamiltonian)&&record(s)&&Array.isArray(s.eigenvalues)&&s.eigenvalues.length>=1&&s.eigenvalues.length<=4&&s.eigenvalues.every(scalar)&&Array.isArray(s.multiplicities)&&s.multiplicities.length===s.eigenvalues.length&&s.multiplicities.every(x=>Number.isInteger(x)&&x>0)&&s.multiplicities.reduce((a,b)=>a+b,0)===4&&s.distinctEigenvalues===s.eigenvalues.length&&bool(s.hasDegeneracy)&&(i===1||matrix(e.comparisonAntiunitaryMatrix,4)&&matrix(e.comparisonAntiunitaryResidual,4)&&bool(e.comparisonAntiunitaryPreservesHamiltonian));}
export function antitranslationModel(r){
 if(!record(r)||r.schema!=='symmetry-lab-antitranslation-1'||r.lab!=='antitranslation'||r.exact!==true||!record(r.input)||Object.keys(r.input).sort().join(',')!=='k,lab,spinful,statePreset'||r.input.lab!=='antitranslation'||!Array.isArray(r.input.k)||r.input.k.length!==3||!r.input.k.every(x=>num(x)||text(x))||!bool(r.input.spinful)||!['basis','complex'].includes(r.input.statePreset))return{status:'invalid'};
 const spinful=r.input.spinful,n=spinful?4:2,b=r.basis,k=r.momentum,t=r.translation,a=r.antiunitary,u=r.unitaryContrast,d=r.decision,c=r.legacyCopy;
 if(!record(b)||b.dimension!==n||b.spinDimension!==(spinful?2:1)||b.statePreset!==r.input.statePreset||!Array.isArray(b.order)||!b.order.every(text)||b.order.join(',')!==(spinful?'A-up,A-down,B-up,B-down':'A,B')||!vector(b.initialState,n)||!text(b.convention))return{status:'invalid'};
 if(!record(k)||!vector(k.k,3)||!vector(k.partner,3)||!bool(k.sameK)||!Array.isArray(k.axisInvariant)||k.axisInvariant.length!==3||!k.axisInvariant.every(bool)||!(k.sameK?vector(k.sewingShift,3):k.sewingShift===null)||!text(k.description))return{status:'invalid'};
 if(!record(t)||!['atK','atPartner','squareAtK'].every(key=>matrix(t[key],2))||!scalar(t.fullCellPhase)||!text(t.convention)||!Array.isArray(t.siteMappings)||t.siteMappings.length!==2||!t.siteMappings.every(s=>record(s)&&text(s.source)&&text(s.target)&&Array.isArray(s.cellShift)&&s.cellShift.length===3&&s.cellShift.every(Number.isInteger)&&vector(s.sourcePosition,3)&&vector(s.unwrappedPosition,3)&&scalar(s.coefficientAtK)))return{status:'invalid'};
 if(!record(a)||!matrix(a.thetaMatrix,spinful?2:1)||a.thetaSquare!==(spinful?-1:1)||!['atK','atPartner','returnSquare','wrongOrdinarySquare','wrongSameFiberProduct'].every(key=>matrix(a[key],n))||!['firstConjugate','firstState','secondConjugate','secondState'].every(key=>vector(a[key],n))||!scalar(a.squareScalar)||!text(a.convention)||a.sameFiberMatrixApplies!==k.sameK||!(k.sameK?scalar(a.sameKOverlap)&&bool(a.sameKOrthogonal):a.sameKOverlap===null&&a.sameKOrthogonal===null))return{status:'invalid'};
 if(!record(u)||u.available!==spinful||u.antiunitary!==false||!text(u.description)||!(spinful?matrix(u.spinRotation,2)&&matrix(u.matrix,n)&&matrix(u.square,n)&&scalar(u.squareScalar)&&u.sameK===true:text(u.reason)))return{status:'invalid'};
 if(!record(d)||d.sameK!==k.sameK||!bool(d.squareIsMinusOne)||!bool(d.kramersConditional)||!text(d.reason)||d.hamiltonianSymmetry!=='not-evaluated'||d.materialDegeneracy!=='not-evaluated'||!Array.isArray(r.counterexamples)||r.counterexamples.length!==2||!r.counterexamples.every(example)||!pattern(r.pattern,spinful))return{status:'invalid'};
 if(!record(c)||!bool(c.available)||!text(c.exactLongitudinalK)||!text(c.description)||!(c.available?record(c.payload)&&Object.keys(c.payload).sort().join(',')==='k,lab,spinful'&&c.payload.lab==='antiferro'&&num(c.payload.k)&&Math.abs(c.payload.k)<=1&&c.payload.spinful===spinful:text(c.reason)))return{status:'invalid'};
 if(!Array.isArray(r.steps)||r.steps.length!==4||!r.steps.every(s=>record(s)&&['id','title','explanation','formula'].every(key=>text(s[key])))||!Array.isArray(r.checks)||!r.checks.length||!r.checks.every(c=>record(c)&&text(c.id)&&text(c.label)&&bool(c.passed))||!Array.isArray(r.notes)||!r.notes.every(text)||!Array.isArray(r.sources)||!r.sources.length||!r.sources.every(s=>record(s)&&text(s.title)&&text(s.url)&&/^https?:\/\//.test(s.url)))return{status:'invalid'};
 return{status:'available',result:r};
}
const math=(p,inline=false)=>inline?`<span class="sax-exact-inline">${mathHTML(p.latex,false)}</span>`:`<div class="sax-matrix" tabindex="0">${mathHTML(p.latex,true)}</div>`;
const formula=s=>`<div class="sax-formula" tabindex="0">${mathHTML(s,true)}</div>`,yes=x=>x?'是':'否';
const table=(title,heads,rows)=>`<div class="sax-scroll" tabindex="0"><table><caption>${esc(title)}</caption><thead><tr>${heads.map(x=>'<th scope="col">'+esc(x)+'</th>').join('')}</tr></thead><tbody>${rows.map(row=>'<tr>'+row.map((x,i)=>i?'<td>'+x+'</td>':'<th scope="row">'+x+'</th>').join('')+'</tr>').join('')}</tbody></table></div>`;
function exampleHTML(e){return`<article class="sax-ant-example"><h5>${esc(e.title)}</h5><p><strong>固定反例 · 自旋 1/2 · 4 维 · k=${esc(JSON.stringify(e.k))} · 无量纲模型能量</strong></p><p>${esc(e.description)}</p><p>保持所声明的 Hamiltonian 对称性：${yes(e.preservesHamiltonian)}；存在简并：${yes(e.spectrum.hasDegeneracy)}。</p><p>本征值：${e.spectrum.eigenvalues.map(s=>math(s,true)).join('，')}</p><details data-sax-native="${e.id}"><summary>展开这个固定反例的矩阵与残差</summary><p>对称算符的矩阵部分：</p>${math(e.symmetryMatrix)}<p>该算符的平方：</p>${math(e.operatorSquare)}<p>反例 Hamiltonian：</p>${math(e.hamiltonian)}<p>对称性残差：</p>${math(e.symmetryResidual)}${e.comparisonAntiunitaryResidual?'<p>同一 Hamiltonian 对反幺正 A 的残差：</p>'+math(e.comparisonAntiunitaryResidual):''}${formula(e.formula)}<p>${esc(e.scope)}</p></details></article>`;}
export function antitranslationResultHTML(r,{stage=1}={}){
 if(antitranslationModel(r).status!=='available')return'<p role="alert">反平移结果不完整，请重新计算。</p>';
 const b=r.basis,k=r.momentum,t=r.translation,a=r.antiunitary,d=r.decision;
 let html='<h4>① 先确定态空间和返回的波矢</h4><p>平方的相位只含纵向分量，但时间反演反转三个分量。先检查三个分量，再讨论同一 k 的伙伴。</p><p>'+esc(b.convention)+'</p><p>有序基：<code data-math-ignore>'+b.order.map(esc).join('，')+'</code>；维数 '+b.dimension+'。</p><p>'+ (r.input.spinful?'本次为自旋 1/2 分支。':'本次为无自旋分支；图中交错箭头只表示抽象时间奇序参量。')+'</p><div class="sax-pair"><section><h5>输入 k（倒格分数）</h5>'+math(k.k)+'</section><section><h5>第一次到达 −k</h5>'+math(k.partner)+'</section></div>'+table('逐分量的整数条件',['分量','2k 为整数？'],['x','y','z'].map((axis,i)=>[axis,yes(k.axisInvariant[i])]))+'<p>回到同一 k 纤维：<strong>'+yes(k.sameK)+'</strong>。</p>'+formula(r.steps[2].formula)+'<p>'+esc(k.description)+'</p>'+(k.sewingShift?'<p>将 −k 识别回 k 的整数倒格矢 G：</p>'+math(k.sewingShift):'<p>此处没有同一纤维识别，不能把两个不同 k 空间直接当作同一个空间。</p>');
 if(stage>=2)html+='<h4>② 跟踪半平移跨过哪一个原胞</h4><p>'+esc(t.convention)+'</p>'+table('站点、未折回位置与整胞相位',['映射','原位置','未折回位置','整胞索引','矩阵列系数'],t.siteMappings.map(s=>[esc(s.source)+' → '+esc(s.target),math(s.sourcePosition,true),math(s.unwrappedPosition,true),'<code data-math-ignore>'+esc(JSON.stringify(s.cellShift))+'</code>',math(s.coefficientAtK,true)]))+'<div class="sax-pair"><section><h5>S(k)</h5>'+math(t.atK)+'</section><section><h5>S(−k)</h5>'+math(t.atPartner)+'</section></div><p>连续两次半平移 S(k)²：</p>'+math(t.squareAtK)+'<p>保留的整胞相位：</p>'+math(t.fullCellPhase)+formula(r.steps[0].formula);
 if(stage>=3)html+='<h4>③ 第二次仍须共轭，并换到返回纤维</h4><p>'+esc(a.convention)+'</p><p>时间反演的内部矩阵 J：</p>'+math(a.thetaMatrix)+'<p>本分支 Θ²='+esc(a.thetaSquare)+'。</p><div class="sax-pair"><section><h5>从 k 到 −k 的矩阵部分</h5>'+math(a.atK)+'</section><section><h5>从 −k 返回的矩阵部分</h5>'+math(a.atPartner)+'</section></div>'+table('逐次作用的复系数链',['步骤','Python 精确态'],[['输入纤维中的初态',math(b.initialState)],['第一次：共轭初态',math(a.firstConjugate)],['第一次：输出到伙伴纤维',math(a.firstState)],['第二次共轭整条中间态',math(a.secondConjugate)],['第二次：返回原纤维',math(a.secondState)]])+formula(r.steps[1].formula)+(k.sameK?'<p>同一纤维内积 ⟨ψ|Aψ⟩：</p>'+math(a.sameKOverlap)+'<p>所选态与其像正交：'+yes(a.sameKOrthogonal)+'。</p>':'<p>同一纤维内积在这里未定义：初态与第一次输出属于不同 k 空间，null 不能读成零。</p>');
 if(stage>=4)html+='<h4>④ 三个条件必须分别检查</h4><p>'+esc(d.reason)+'</p>'+formula(r.steps[3].formula)+table('本次输入的条件判据',['条件','返回判断'],[['回到同一 k',yes(d.sameK)],['正确返回平方为 −I',yes(d.squareIsMinusOne)],['再假设 H 具有 A 对称时可推出配对',yes(d.kramersConditional)],['实际 Hamiltonian 对称性','<code data-math-ignore>'+esc(d.hamiltonianSymmetry)+'</code>'],['实际材料简并','<code data-math-ignore>'+esc(d.materialDegeneracy)+'</code>']])+'<p>条件成立仍不表示本页已经验证材料 Hamiltonian 或计算出能带。</p><p>正确的跨纤维返回平方：</p>'+math(a.returnSquare)+'<div class="sax-pair"><section><h5>错误对照：同一矩阵直接平方，漏掉共轭</h5>'+math(a.wrongOrdinarySquare)+'</section><section><h5>错误对照：共轭后仍重复使用同一纤维矩阵</h5>'+math(a.wrongSameFiberProduct)+'</section></div><p>特殊 k 上错误算法也可能碰巧给出相同数值；请改到纵向一般点或 1/7 后再比较。</p>'+(r.unitaryContrast.available?'<details data-sax-native="unitary"><summary>本次输入的幺正 G 对照</summary><p>'+esc(r.unitaryContrast.description)+'</p><p>先看不作用于实空间的独立自旋二重旋转 D(C₂x)：</p>'+math(r.unitaryContrast.spinRotation)+'<p>与同一个半平移矩阵 S(k) 取直积，得到本次幺正 G(k)。</p>'+math(r.unitaryContrast.matrix)+'<p>G(k)²：</p>'+math(r.unitaryContrast.square)+'</details>':'<p>'+esc(r.unitaryContrast.reason)+'</p>')+'<p class="notice"><strong>以下两个反例固定为自旋 1/2 的四维模型，分别位于 Γ 和 Z；不随上方 k、初态或无自旋开关改变。能量均为无量纲。</strong></p>'+r.counterexamples.map(exampleHTML).join('');
 return html;
}

const select=(id,label,rows,value)=>`<label for="sax-${id}">${esc(label)}<select id="sax-${id}">${rows.map(([key,title])=>`<option value="${esc(key)}"${String(key)===String(value)?' selected':''}>${esc(title)}</option>`).join('')}</select></label>`;
const kInput=(id,label,value)=>`<label for="sax-${id}">${esc(label)}<input id="sax-${id}" type="text" inputmode="text" maxlength="48" spellcheck="false" value="${esc(value)}" required></label>`;
const readOpen=node=>typeof node?.open==='boolean'?node.open:node?.getAttribute?.('open')!==null;
const identity=input=>JSON.stringify([input?.lab,input?.k,input?.spinful,input?.statePreset]);
const feedback='半平移的平方只含 k_z，但时间反演反转全部三个分量。横向一般点去往另一个纤维；还须分别检查正确平方和 Hamiltonian 对称性。';

