 const store=stateStore instanceof Map?stateStore:new Map(),key='panel:'+lessonId,prior=store.get(key),state={raw:defaults(),result:null,input:null,stage:1,frame:0,note:'',prediction:'',checked:false,details:{},camera:{},error:'',copyStatus:'',...(record(prior)?clone(prior):{})};
 state.raw={...defaults(),...(record(state.raw)?state.raw:{})};if(!Number.isInteger(state.stage)||state.stage<1||state.stage>4)state.stage=1;if(!Number.isInteger(state.frame)||state.frame<0)state.frame=0;if(!record(state.details))state.details={};if(!text(state.note))state.note='';if(!text(state.prediction))state.prediction='';
